#!/usr/bin/env node
/**
 * Attribute the bytes of the production JS chunk to source modules, from its source map.
 *
 * Reads `dist/analyze/assets/index-*.js` + `.map` (produced by
 * `vite build --config tools/analysis/vite.attribution.config.ts`), decodes the VLQ
 * mappings and charges every generated byte to the source of the segment that covers it
 * (the same rule source-map-explorer uses; the two agree to within 0.2 % here).
 *
 * Prints a bucket table (vendor / app areas / PF1e tiers) and writes the per-file result to
 * `dist/analyze/attribution.json` for `tools/analysis/pf1eCoupling.mjs`.
 *
 *   node tools/analysis/bundleAttribution.mjs [--top N]
 */
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const assets = resolve(root, "dist/analyze/assets");
const top = Number(process.argv[process.argv.indexOf("--top") + 1]) || 0;

const chunkName = readdirSync(assets).find((f) => /^index-.*\.js$/.test(f));
if (!chunkName) {
  console.error("no dist/analyze/assets/index-*.js — run the attribution build first");
  process.exit(1);
}
const code = readFileSync(resolve(assets, chunkName), "utf8");
const map = JSON.parse(readFileSync(resolve(assets, `${chunkName}.map`), "utf8"));

// --- VLQ decoding -------------------------------------------------------------------------
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const charToInt = new Map([...B64].map((c, i) => [c, i]));
function decodeSegment(seg) {
  const out = [];
  let value = 0;
  let shift = 0;
  for (const ch of seg) {
    const digit = charToInt.get(ch);
    const cont = digit & 32;
    value += (digit & 31) << shift;
    if (cont) {
      shift += 5;
    } else {
      const neg = value & 1;
      value >>= 1;
      out.push(neg ? -value : value);
      value = 0;
      shift = 0;
    }
  }
  return out;
}

// --- byte attribution ---------------------------------------------------------------------
const lines = code.split("\n");
const sources = map.sources.map((s) =>
  s
    .replace(/^.*?ArenaStar_VTT\//, "")
    .replace(/^(\.\.\/)+/, "")
    .replace(/^\0/, ""),
);
const bytes = new Map(); // source index (or -1 for unmapped) -> bytes
const charge = (idx, n) => bytes.set(idx, (bytes.get(idx) ?? 0) + n);
let srcIdx = 0;
const mappingLines = map.mappings.split(";");
for (let ln = 0; ln < lines.length; ln++) {
  const lineLen = Buffer.byteLength(lines[ln], "utf8") + 1; // + newline
  const segs = (mappingLines[ln] ?? "").split(",").filter(Boolean);
  if (segs.length === 0) {
    charge(-1, lineLen);
    continue;
  }
  let col = 0;
  const cols = [];
  for (const seg of segs) {
    const f = decodeSegment(seg);
    col += f[0];
    if (f.length >= 4) srcIdx += f[1];
    cols.push([col, f.length >= 4 ? srcIdx : -1]);
  }
  // Bytes before the first segment are unmapped; each segment owns up to the next one.
  if (cols[0][0] > 0) charge(-1, Buffer.byteLength(lines[ln].slice(0, cols[0][0]), "utf8"));
  for (let i = 0; i < cols.length; i++) {
    const [c, idx] = cols[i];
    const end = i + 1 < cols.length ? cols[i + 1][0] : lines[ln].length;
    charge(idx, Buffer.byteLength(lines[ln].slice(c, end), "utf8") + (i + 1 === cols.length ? 1 : 0));
  }
}

const files = {};
for (const [idx, n] of bytes) files[idx === -1 ? "[unmapped]" : sources[idx]] = (files[idx === -1 ? "[unmapped]" : sources[idx]] ?? 0) + n;
const total = Object.values(files).reduce((a, b) => a + b, 0);

// --- buckets ------------------------------------------------------------------------------
const buckets = [
  ["vendor: pixi.js", (f) => /node_modules\/(pixi\.js|@pixi|earcut|eventemitter3|ismobilejs|parse-svg-path|@xmldom)/.test(f)],
  ["vendor: three (3D dice)", (f) => /node_modules\/three\//.test(f)],
  ["vendor: svelte runtime", (f) => /node_modules\/svelte/.test(f)],
  ["vendor: other", (f) => /node_modules\//.test(f)],
  ["PF1e: tactical logic (src/packages/pf1e, excl. import/)", (f) => /^src\/packages\/pf1e\/(?!import\/)/.test(f)],
  ["PF1e: importers (src/packages/pf1e/import)", (f) => /^src\/packages\/pf1e\/import\//.test(f)],
  ["PF1e: UI (src/ui/**/pf1e*|PF1e*)", (f) => /^src\/ui\/.*pf1e/i.test(f)],
  ["PF1e: strategic ruleset (massBattlePf1e)", (f) => /pf1e/i.test(f)],
  ["app: ui (svelte, non-PF1e)", (f) => /^src\/ui\//.test(f)],
  ["app: core", (f) => /^src\/core\//.test(f)],
  ["app: host/client/net/storage/workers", (f) => /^src\/(net|host|client|storage|workers)\//.test(f)],
  ["app: canvas", (f) => /^src\/canvas\//.test(f)],
  ["app: app shell (App/JoinApp/boot/e2eHook/agentBridge)", (f) => /^src\/app\//.test(f)],
  ["app: dice/audio/sim/packages(AIS, loader)", (f) => /^src\/(dice|audio|sim|packages)\//.test(f)],
  ["unmapped / other", () => true],
];
const sums = new Map(buckets.map(([b]) => [b, 0]));
for (const [f, n] of Object.entries(files)) {
  for (const [b, test] of buckets) {
    if (test(f)) {
      sums.set(b, sums.get(b) + n);
      break;
    }
  }
}
console.log(`chunk ${chunkName}: ${total} bytes attributed (file on disk: ${Buffer.byteLength(code)})`);
for (const [b, n] of [...sums].sort((a, b) => b[1] - a[1])) {
  console.log(String(n).padStart(9), `${((100 * n) / total).toFixed(1).padStart(5)}%`, b);
}
if (top) {
  console.log(`\n--- top ${top} sources ---`);
  for (const [f, n] of Object.entries(files).sort((a, b) => b[1] - a[1]).slice(0, top)) console.log(String(n).padStart(9), f);
}
writeFileSync(resolve(root, "dist/analyze/attribution.json"), JSON.stringify({ chunk: chunkName, total, files }, null, 1));
console.log("\nwrote dist/analyze/attribution.json");
